    difference
    >>> calculateDifferenceBetweenTimePeriod("00:00:00","23:59:59")
    '23:59:59'
    """
def calculateDifferenceBetweenTimePeriod(time1: str, time2: str) -> str {
    l1 = time1.split(':');
    l2 = time2.split(":");
    sec1 = int(l1[2]);
    min1 = int(l1[1]);
    hr1 = int(l1[0]);
    sec2 = int(l2[2]);
    min2 = int(l2[1]);
    hr2 = int(l2[0]);
