        sec = sec1 - sec2;
    } else {
        sec = sec2 - sec1;
    }
    if min1 > min2 {
        min3 = min1 - min2;
    } else {
        min3 = min2 - min1;
    }
    if hr1 > hr2 {
        hr = hr1 - hr2;
    } else {
        hr = hr2 - hr1;
    }
    hr = str(hr);
    min3 = str(min3);
    sec = str(sec);
    string = hr + ':' + min3 + ':' + sec;
