"""
    Recursively updates nested directories.

    Args:
        to_update (dict or collections.Mapping):
            dict to update.
        update (dict or collections.Mapping):
            dict containing new values.

    Returns:
        dict: to_update
    """
def recursive_update(to_update: dict[str, object], update: dict[str, object]) -> dict[str, object] {
    if update {
        for (key, value) in update.items() {
            if isinstance(value, dict) {
                value = recursive_update(to_update.get(key, {}) as dict[str, object], value as dict[str, object]);
            }
            to_update[key] = value;
        }
    }
    return to_update;
}
