def mGCD(a: int, b: int, m: int = 1) -> int {
    a1 = a % m;
    p = 1;
    while b > 0 {
        if b % 2 == 1 {
            p *= a1;
            p = p % m;
        }
        b /= 2;
        a1 = (a1 * a1) % m;
