def find_subsequence(subseq: list[int], seq: list[int]) -> bool {
    (i, n, m) = (-1, len(seq), len(subseq));
    try {
        while True {
            i = seq.index(subseq[0], i + 1, n - m + 1);
            if subseq == seq[i:(i + m)] {
                return True;
            }
        }
    } except ValueError {
