def decode(to_be_decoded: str) -> str {
    to_be_decoded_list = list(to_be_decoded);
    decoded_str_as_list = list();
    num_to_print_as_list = list();
    for c in to_be_decoded_list {
        if c.isdigit() {
            num_to_print_as_list.append(c);
