def build_ranges(page_list: list[int | str]) -> str {
    page_list.append(-1);
    output = [];
    last = int(page_list[0]) - 1;
    beginning = int(page_list[0]);
    for i in page_list {
        i = int(i);
        if i != last + 1 {
            output.append([str(beginning), str(last)]);
