def transition(color1: int, color2: int, position: float) -> int {
    r1 = color1 >> 16;
    g1 = color1 >> 8 & 255;
    b1 = color1 & 255;
    r2 = color2 >> 16;
    g2 = color2 >> 8 & 255;
    b2 = color2 & 255;
    r = int(r1 + ((r2 - r1) * position) // 1) << 16;
    g = int(g1 + ((g2 - g1) * position) // 1) << 8;
    b = int(b1 + ((b2 - b1) * position) // 1);
    return r | g | b;
}
