"""
    Flatten nested json to return a dict without nested values. Lists without nested values will
    be ignored, and lists of dicts will only return the first key value pair for each key. Useful
    for passing nested json to validation methods.
    """
def flatten_json(json: dict[str, object] | list[object] | str | int | float | bool | None) -> dict[str, object | str | int | float | bool | None] {
    out = {};
    def flatten(x: dict[str, object] | list[object] | str | int | float | bool | None, name: str = '') {
        if isinstance(x, dict) {
            for (k, v) in x.items() {
                flatten(v, k);
            }
        } elif isinstance(x, list) {
            for a in x {
                flatten(a);
            }
        } elif (name != '') and (name not in out) {
            out[name] = x;
        }
    }
    flatten(json);
    return out;
}
