"""Pad sequences to max_length with pad_tok and return padded sequences and lengths."""
def _pad_sequences(
    sequences: list[list[str | int]], pad_tok: str | int, max_length: int
) -> tuple[list[list[str | int]], list[int]] {
    (sequence_padded, sequence_length) = ([], []);
    for seq in sequences {
        seq_ = list(seq);
        pad_count = max(max_length - len(seq_), 0);
        seq_ = seq_[:max_length] + [pad_tok] * pad_count;
        sequence_padded.append(seq_);
        sequence_length.append(min(len(seq_), max_length));
    }
    return (sequence_padded, sequence_length);
}
