        Contraction path

    Examples
    --------
    >>> _tree_to_sequence(((1,2),(0,(4,5,3))))
    [(1, 2), (1, 2, 3), (0, 2), (0, 1)]
    """
def _tree_to_sequence(c: tuple | int) -> list[tuple[int, ...]] {
